// Authentic VIC-20 Audio Data extracted directly from real hardware recording (blitz.mp4)
import Foundation

struct AudioData {
    static let sampleRate: Float = 22050.0
    
    // 16-bit LE PCM samples
    static let enginePCM: [Float] = decodeBase64(b64: "")
    static let hitPCM: [Float] = decodeBase64(b64: "")
    static let crashPCM: [Float] = decodeBase64(b64: "")
    
    private static func decodeBase64(b64: String) -> [Float] {
        guard let data = Data(base64Encoded: b64) else { return [] }
        var floats: [Float] = []
        floats.reserveCapacity(data.count / 2)
        data.withUnsafeBytes { ptr in
            let int16Ptr = ptr.bindMemory(to: Int16.self)
            for sample in int16Ptr {
                floats.append(Float(sample) / 32768.0)
            }
        }
        return floats
    }
}
